using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Ara {public static class AdherenceTests {
 static void Yes(bool ok,string why){if(!ok)throw new Exception(why);}static Day D(State s){return s.Days[0];}
 public static State New(bool work=true){var s=State.New();var d=s.GetDay(new DateTime(2026,10,18));d.Wake=d.Wake.Date.AddHours(8);GridEngine.Ensure(s,d);if(work)d.GridBase.Add(new CellBlock{Id="work-plan",Start=d.Wake.Date.AddHours(9),Count=6,Category="작업",Name="집중 작업",Minimum=1});return s;}
 public static State Edit(State s,PhoneCommand c){var old=Store.Clone(s);var next=Store.Clone(s);var d=D(next);c.date=d.Date;PhoneEditing.Apply(next,d,c);BlockTools.Merge(d.Records);if(c.lane==0)BlockTools.Merge(d.GridBase);PlanHistory.Advance(old,D(old),next,d);GridEngine.Build(next,d);return next;}
 static State Work(int first=54,int last=59){return Edit(New(),new PhoneCommand{op="category",lane=1,first=first,last=last,category="작업"});}
 static decimal? Score(State s){return Adherence.Score(D(s));}
 public static void Run(Action<string,Action> check,string dir){
 check("adherence: exact and ten-minute errors use compact nine-point scale",()=>{Yes(Score(Work())==9&&Score(Work(55,60))==8&&Score(Work(53,58))==8,"nine and symmetric eight");});
 check("adherence: ninety-minute and larger errors floor at zero",()=>{Yes(Score(Work(63,68))==0&&Score(Work(70,75))==0,"never negative");});
 check("adherence: start and end equally weighted",()=>{Yes(Score(Work(54,58))==8.5m,"one exact boundary and one ten-minute error");});
 check("adherence: meal completion is not evaluated",()=>{var s=New(false);var m=GridEngine.Build(s,D(s)).Blocks.First(b=>b.MealId=="b1");s=Edit(s,new PhoneCommand{op="copy",lane=1,first=(int)(m.Start-D(s).Wake.Date).TotalMinutes/10,last=(int)(m.Start-D(s).Wake.Date).TotalMinutes/10,sourceId=m.Id});Yes(Score(s)==9&&JsonMap.Map(JsonMap.Items(Adherence.Report(D(s)),"actions")[0])["end_score"]==null,"early finish stays nine");});
 check("adherence: own late meal cannot rewrite its comparison plan",()=>{var s=New(false);var m=GridEngine.Build(s,D(s)).Blocks.First(b=>b.MealId=="b1");int start=(int)(m.Start-D(s).Wake.Date).TotalMinutes/10;s=Edit(s,new PhoneCommand{op="copy",lane=1,first=start+2,last=start+4,sourceId=m.Id});Yes(Score(s)==7,"twenty-minute start error");var second=GridEngine.Build(s,D(s)).DisplayBlocks.First(b=>b.MealId=="b6");start=(int)(second.Start-D(s).Wake.Date).TotalMinutes/10;s=Edit(s,new PhoneCommand{op="copy",lane=1,first=start,last=start+2,sourceId=second.Id});Yes(Convert.ToDecimal(JsonMap.Map(JsonMap.Items(Adherence.Report(D(s)),"actions").Last())["score"])==9,"next meal uses adjusted plan");});
 check("adherence: moving a past upper plan does not improve score",()=>{var s=Edit(Work(55,60),new PhoneCommand{op="move",lane=0,id="work-plan",first=55,last=60});Yes(Score(s)==8,"immutable target");});
 check("adherence: focus satisfaction splits do not multiply actions",()=>{var s=Edit(Work(55,60),new PhoneCommand{op="score",lane=1,first=57,last=58,score=5});s=Edit(s,new PhoneCommand{op="satisfaction",lane=1,first=56,last=57,satisfaction=0});Yes(Score(s)==8&&Convert.ToInt32(Adherence.Report(D(s))["evaluated_actions"])==1,"one activity");});
 check("adherence: old records without baseline stay unrated",()=>{var s=New();var b=D(s).GridBase.First(x=>x.Id=="work-plan").Copy();b.Id="legacy";D(s).Records.Add(b);s=Edit(s,new PhoneCommand{op="score",lane=1,first=54,last=59,score=3});Yes(Score(s)==null,"unknown past not fabricated");});
 check("adherence: no records and unplanned activity have no score",()=>{var s=Edit(New(false),new PhoneCommand{op="category",lane=1,first=70,last=72,category="학습"});Yes(Score(New())==null&&Score(s)==null,"unplanned excluded");});
 check("adherence: record correction and deletion preserve references",()=>{var s=Work(55,60);string id=D(s).Records[0].Id;s=Edit(s,new PhoneCommand{op="move",lane=1,id=id,first=54,last=59});Yes(Score(s)==9,"corrected against old reference");s=Edit(s,new PhoneCommand{op="delete",lane=1,first=54,last=59});Yes(Score(s)==null,"no score after deletion");});
 check("adherence: saved JSON roundtrip preserves original plan and export metadata",()=>{var s=Work(55,60);var copy=PhoneCodec.Read<State>(PhoneCodec.Json(s));Yes(Score(copy)==8&&JsonMap.Items(Adherence.Report(D(copy)),"plan_revisions").Length>0,"persisted");var payload=NotionDiary.Payload(copy,D(copy).Date);var data=JsonMap.Child(payload,"diary");Yes(data.ContainsKey("adherence")&&JsonMap.Child(JsonMap.Child(data,"adherence"),"initial_plan_match").ContainsKey("percent"),"analysis export");});
 check("adherence: independent devices merge distinct activity references",()=>{var baseline=New();D(baseline).GridBase.Add(new CellBlock{Id="study-plan",Start=D(baseline).Wake.Date.AddHours(11.5),Count=3,Category="학습",Name="읽기"});var local=Edit(baseline,new PhoneCommand{op="category",lane=1,first=54,last=59,category="작업"});var remote=Edit(baseline,new PhoneCommand{op="category",lane=1,first=69,last=71,category="학습"});var merged=ReplicaSync.Merge(baseline,local,remote,D(baseline).Date);Yes(Score(merged)==9&&Convert.ToInt32(Adherence.Report(D(merged))["evaluated_actions"])==2,"both references retained");});
 check("adherence: action average is not duration weighted",()=>{var s=New();D(s).GridBase.Add(new CellBlock{Id="study-plan",Start=D(s).Wake.Date.AddHours(11.5),Count=1,Category="학습",Name="읽기"});s=Edit(s,new PhoneCommand{op="category",lane=1,first=54,last=59,category="작업"});s=Edit(s,new PhoneCommand{op="category",lane=1,first=70,last=70,category="학습"});Yes(Score(s)==8.5m,"one-hour nine and ten-minute eight average8.5");});
 }} }
